templates.js:
function trap(height) {
    let left = 0, right = height.length - 1;
    let leftMax = 0, rightMax = 0, water = 0;
    while (left < right) {
        if (height[left] < height[right]) {
            if (height[left] >= leftMax) leftMax = height[left];
            else water += leftMax - height[left];
            left++;
        } else {
            if (height[right] >= rightMax) rightMax = height[right];
            else water += rightMax - height[right];
            right--;
        }
    }
    return water;
}

templates.py:
def trap(height):
    l, r = 0, len(height) - 1
    l_max = r_max = water = 0
    while l < r:
        if height[l] < height[r]:
            if height[l] >= l_max: l_max = height[l]
            else: water += l_max - height[l]
            l += 1
        else:
            if height[r] >= r_max: r_max = height[r]
            else: water += r_max - height[r]
            r -= 1
    return water

templates.cpp:
int trap(std::vector<int>& height) {
    int l = 0, r = height.size() - 1, lMax = 0, rMax = 0, water = 0;
    while (l < r) {
        if (height[l] < height[r]) {
            if (height[l] >= lMax) lMax = height[l];
            else water += lMax - height[l];
            l++;
        } else {
            if (height[r] >= rMax) rMax = height[r];
            else water += rMax - height[r];
            r--;
        }
    }
    return water;
}

templates.java:
public int trap(int[] height) {
    int l = 0, r = height.length - 1, lMax = 0, rMax = 0, water = 0;
    while (l < r) {
        if (height[l] < height[r]) {
            if (height[l] >= lMax) lMax = height[l];
            else water += lMax - height[l];
            l++;
        } else {
            if (height[r] >= rMax) rMax = height[r];
            else water += rMax - height[r];
            r--;
        }
    }
    return water;
}

templates.go:
func trap(height []int) int {
    l, r := 0, len(height)-1
    lMax, rMax, water := 0, 0, 0
    for l < r {
        if height[l] < height[r] {
            if height[l] >= lMax { lMax = height[l] } else { water += lMax - height[l] }
            l++
        } else {
            if height[r] >= rMax { rMax = height[r] } else { water += rMax - height[r] }
            r--
        }
    }
    return water
}

